<script setup lang="ts">
import { computed } from 'vue'
import { useStudyStore } from '../stores/useStudyStore'
import { useGoogleServices } from '../composables/useGoogleServices'
import NavbarHeader from '../components/common/NavbarHeader.vue'
import { useToast } from '../composables/useToast'
const store = useStudyStore(); const google = useGoogleServices(); const toast = useToast(); const total = computed(() => store.weeks.reduce((n, w) => n + w.subtemas.length, 0)); const progress = computed(() => total.value ? Math.round(store.totalCompleted / total.value * 100) : 0); const distractionMinutes = computed(() => Math.round(store.incidents.reduce((n, i) => n + i.duracionSegundos, 0) / 60))
async function backup() { try { await google.backupProgress(); toast.showSuccess('Respaldo guardado en Google Drive.') } catch (e) { toast.showError(e instanceof Error ? e.message : 'No se pudo respaldar.') } }
</script>
<template><main class="mx-auto max-w-7xl px-5 py-8"><h1 class="text-3xl font-black text-white">Progreso & Analíticas</h1><div class="mt-6 grid gap-4 sm:grid-cols-3"><div class="card"><p class="text-sm text-slate-400">Racha actual</p><strong class="text-3xl text-white">{{ store.streak }} días</strong></div><div class="card"><p class="text-sm text-slate-400">Progreso del ciclo</p><strong class="text-3xl text-white">{{ progress }}%</strong></div><div class="card"><p class="text-sm text-slate-400">Interrupciones</p><strong class="text-3xl text-white">{{ store.incidents.length }}</strong><p class="text-sm text-slate-400">{{ distractionMinutes }} minutos registrados</p></div></div><div class="card mt-6"><div class="mb-3 flex justify-between"><h2 class="font-bold text-white">Progreso global</h2><span>{{ store.totalCompleted }} / {{ total }} subtemas</span></div><div class="h-4 rounded-full bg-slate-800"><div class="h-full rounded-full bg-indigo-500" :style="{ width: `${progress}%` }" /></div></div><button class="btn-primary mt-6" :disabled="!store.isGoogleTokenValid" @click="backup">Forzar respaldo en Google Drive</button></main></template>
